[CmdletBinding()]
param(
    [string]$ProjectRoot,
    [string]$KeyArtPath='art_refs/characters/iris/concept/Iris_KeyArt_REVIEW_v002.png',
    [string]$Reference3DPath='art_refs/characters/iris/3d_reference/Iris_3DReference_REVIEW_v002.png',
    [string]$OutputPath='art_refs/characters/iris/3d_reference/Iris_2DTo3DTranslation_REVIEW_v001.png',
    [switch]$Force
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))}else{$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot)}
function Resolve-In([string]$Path){$p=if([IO.Path]::IsPathRooted($Path)){$Path}else{Join-Path $ProjectRoot $Path};return (Resolve-Path -LiteralPath $p -ErrorAction Stop).Path}
function Resolve-Out([string]$Path){if([IO.Path]::IsPathRooted($Path)){return [IO.Path]::GetFullPath($Path)};return [IO.Path]::GetFullPath((Join-Path $ProjectRoot $Path))}
function C([string]$Hex){return [Drawing.ColorTranslator]::FromHtml($Hex)}
function F([float]$Size,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular){try{return [Drawing.Font]::new('Segoe UI',$Size,$Style,[Drawing.GraphicsUnit]::Pixel)}catch{return [Drawing.Font]::new([Drawing.FontFamily]::GenericSansSerif,$Size,$Style,[Drawing.GraphicsUnit]::Pixel)}}
function Init-G([Drawing.Graphics]$G){$G.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias;$G.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$G.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::HighQuality;$G.CompositingQuality=[Drawing.Drawing2D.CompositingQuality]::HighQuality;$G.TextRenderingHint=[Drawing.Text.TextRenderingHint]::AntiAliasGridFit}
function Draw-Text([Drawing.Graphics]$G,[string]$Text,[Drawing.Font]$Font,[Drawing.Brush]$Brush,[Drawing.RectangleF]$Rect,[Drawing.StringAlignment]$Align=[Drawing.StringAlignment]::Near,[Drawing.StringAlignment]$Line=[Drawing.StringAlignment]::Near){$sf=[Drawing.StringFormat]::new();try{$sf.Alignment=$Align;$sf.LineAlignment=$Line;$sf.Trimming=[Drawing.StringTrimming]::EllipsisCharacter;$G.DrawString($Text,$Font,$Brush,$Rect,$sf)}finally{$sf.Dispose()}}
function Draw-Chip([Drawing.Graphics]$G,[string]$Text,[Drawing.RectangleF]$Rect,[Drawing.Color]$Color,[Drawing.Font]$Font){$fill=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(52,$Color));$pen=[Drawing.Pen]::new($Color,2);$white=[Drawing.SolidBrush]::new([Drawing.Color]::White);try{$G.FillRectangle($fill,$Rect);$G.DrawRectangle($pen,$Rect.X,$Rect.Y,$Rect.Width,$Rect.Height);Draw-Text $G $Text $Font $white $Rect Center Center}finally{$white.Dispose();$pen.Dispose();$fill.Dispose()}}
function Draw-Figure([Drawing.Graphics]$G,[Drawing.Image]$Image,[Drawing.RectangleF]$Panel,[string]$Label,[string]$Sub,[int]$Crown,[int]$Chin,[int]$Sole,[Drawing.Color]$Accent,[Drawing.Font]$Title,[Drawing.Font]$Small,[Drawing.Font]$GuideFont){$ratio=($Sole-$Crown)/[double]($Chin-$Crown);$tc=300.0;$ts=1000.0;$scale=($ts-$tc)/($Sole-$Crown);$w=$Image.Width*$scale;$h=$Image.Height*$scale;$x=$Panel.X+($Panel.Width-$w)/2;$y=$tc-$Crown*$scale;$fill=[Drawing.SolidBrush]::new((C '#0A1423'));$border=[Drawing.Pen]::new((C '#2A3E57'),2);$ab=[Drawing.SolidBrush]::new($Accent);$white=[Drawing.SolidBrush]::new((C '#F4FAFF'));$muted=[Drawing.SolidBrush]::new((C '#91A6BB'));$guide=[Drawing.Pen]::new([Drawing.Color]::FromArgb(175,$Accent),1.6);try{$G.FillRectangle($fill,$Panel);$G.DrawRectangle($border,$Panel.X,$Panel.Y,$Panel.Width,$Panel.Height);$G.FillRectangle($ab,$Panel.X+18,$Panel.Y+20,7,49);Draw-Text $G $Label $Title $white ([Drawing.RectangleF]::new($Panel.X+42,$Panel.Y+16,$Panel.Width-60,36));Draw-Text $G $Sub $Small $muted ([Drawing.RectangleF]::new($Panel.X+42,$Panel.Y+51,$Panel.Width-60,30));$old=$G.Clip;try{$G.SetClip([Drawing.RectangleF]::new($Panel.X+2,$Panel.Y+84,$Panel.Width-4,$Panel.Height-86));$G.DrawImage($Image,[Drawing.Rectangle]::new([int]$x,[int]$y,[int]$w,[int]$h))}finally{$G.Clip=$old;$old.Dispose()};$step=($ts-$tc)/$ratio;for($i=0;$i-le[Math]::Floor($ratio);$i++){$gy=$tc+$i*$step;$guide.DashStyle=if($i-eq0){[Drawing.Drawing2D.DashStyle]::Solid}else{[Drawing.Drawing2D.DashStyle]::Dash};$G.DrawLine($guide,$Panel.X+12,$gy,$Panel.Right-12,$gy);Draw-Text $G "${i}H" $GuideFont $ab ([Drawing.RectangleF]::new($Panel.Right-58,$gy-18,42,24)) Far Center};$guide.DashStyle=[Drawing.Drawing2D.DashStyle]::Solid;$G.DrawLine($guide,$Panel.X+12,$ts,$Panel.Right-12,$ts);Draw-Text $G (('{0:F2}H'-f$ratio)) $GuideFont $ab ([Drawing.RectangleF]::new($Panel.Right-90,$ts-23,72,24)) Far Center}finally{$guide.Dispose();$muted.Dispose();$white.Dispose();$ab.Dispose();$border.Dispose();$fill.Dispose()}}
function Draw-Card([Drawing.Graphics]$G,[string]$Title,[string[]]$Lines,[Drawing.RectangleF]$Rect,[Drawing.Color]$Accent,[Drawing.Font]$TitleFont,[Drawing.Font]$BodyFont){$fill=[Drawing.SolidBrush]::new((C '#111B2B'));$border=[Drawing.Pen]::new((C '#2D415A'),1.5);$ab=[Drawing.SolidBrush]::new($Accent);$white=[Drawing.SolidBrush]::new((C '#F4FAFF'));$muted=[Drawing.SolidBrush]::new((C '#B5C7D8'));try{$G.FillRectangle($fill,$Rect);$G.DrawRectangle($border,$Rect.X,$Rect.Y,$Rect.Width,$Rect.Height);$G.FillRectangle($ab,$Rect.X,$Rect.Y,6,$Rect.Height);Draw-Text $G $Title $TitleFont $white ([Drawing.RectangleF]::new($Rect.X+22,$Rect.Y+12,$Rect.Width-38,28));$y=$Rect.Y+47;foreach($line in $Lines){Draw-Text $G ('- '+$line) $BodyFont $muted ([Drawing.RectangleF]::new($Rect.X+24,$y,$Rect.Width-42,26));$y+=27}}finally{$muted.Dispose();$white.Dispose();$ab.Dispose();$border.Dispose();$fill.Dispose()}}

$key=[Drawing.Bitmap]::FromFile((Resolve-In $KeyArtPath));$ref=[Drawing.Bitmap]::FromFile((Resolve-In $Reference3DPath));$out=Resolve-Out $OutputPath
if($key.Width-ne864-or$key.Height-ne1821){throw 'KeyArt dimensions changed.'};if($ref.Width-ne887-or$ref.Height-ne1774){throw '3D reference dimensions changed.'};if([IO.File]::Exists($out)-and-not$Force){throw "Output exists: $out. Use -Force."};$dir=Split-Path -Parent $out;if(-not[IO.Directory]::Exists($dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null}
$o=[Drawing.Bitmap]::new(2048,1440,[Drawing.Imaging.PixelFormat]::Format24bppRgb);$g=[Drawing.Graphics]::FromImage($o);$title=F 38 ([Drawing.FontStyle]::Bold);$sub=F 17;$panelTitle=F 25 ([Drawing.FontStyle]::Bold);$small=F 15;$chip=F 16 ([Drawing.FontStyle]::Bold);$guideFont=F 13 ([Drawing.FontStyle]::Bold);$cardTitle=F 18 ([Drawing.FontStyle]::Bold);$cardBody=F 15;$status=F 18 ([Drawing.FontStyle]::Bold);$statusSmall=F 15
try{Init-G $g;$bg=[Drawing.Drawing2D.LinearGradientBrush]::new([Drawing.Rectangle]::new(0,0,2048,1440),(C '#07111F'),(C '#121326'),25);$white=[Drawing.SolidBrush]::new((C '#F4FAFF'));$muted=[Drawing.SolidBrush]::new((C '#8EA5BA'));$line=[Drawing.Pen]::new((C '#3B294D'),2);try{$g.FillRectangle($bg,0,0,2048,1440);$g.DrawLine($line,42,105,2006,105);Draw-Text $g 'IRIS / 2D TO 3D TRANSLATION' $title $white ([Drawing.RectangleF]::new(48,24,820,52));Draw-Text $g 'REVIEW v001 / observation-lance sniper identity and gameplay simplification' $sub $muted ([Drawing.RectangleF]::new(50,75,950,26));Draw-Chip $g '2D 7.30H / PASS' ([Drawing.RectangleF]::new(1035,33,245,48)) (C '#61E6A5') $chip;Draw-Chip $g '3D 5.75H / CONCEPT PASS' ([Drawing.RectangleF]::new(1295,33,305,48)) (C '#F7B95A') $chip;Draw-Chip $g 'APPROVAL / PENDING' ([Drawing.RectangleF]::new(1615,33,370,48)) (C '#C93149') $chip;Draw-Figure $g $key ([Drawing.RectangleF]::new(44,126,604,1042)) '2D KEY ART' '7.30H / elegant vertical fashion source' 104 270 1316 (C '#61E6A5') $panelTitle $small $guideFont;Draw-Figure $g $ref ([Drawing.RectangleF]::new(670,126,604,1042)) '3D STYLE REFERENCE' '5.75H concept / compact precision mass' 188 410 1464 (C '#F7B95A') $panelTitle $small $guideFont;Draw-Card $g 'IDENTITY LOCK' @('deep-plum straight hair + silver band','cold-white split observation coat','near-height energy lance + crimson aim') ([Drawing.RectangleF]::new(1302,126,702,156)) (C '#A78BFA') $cardTitle $cardBody;Draw-Card $g 'EXPAND' @('head, sharp eyes, hands and boots','visor red dot + lance grip / fold hinge','coat fork tips and feminine waist read') ([Drawing.RectangleF]::new(1302,296,702,156)) (C '#61E6A5') $cardTitle $cardBody;Draw-Card $g 'DELETE' @('micro seams, tiny straps and scope noise','unsupported small observation modules','2D long-leg fashion exaggeration') ([Drawing.RectangleF]::new(1302,466,702,156)) (C '#C93149') $cardTitle $cardBody;Draw-Card $g 'COMBINE' @('coat tails into two physics panels','range modules into one hip cluster','lance telescope into three major blocks') ([Drawing.RectangleF]::new(1302,636,702,156)) (C '#5A4A70') $cardTitle $cardBody;Draw-Card $g 'PHYSICS / CAMERA' @('simulate hair lower third + two coat panels','clamp away from face, scope and shoulders','stow lance to prevent long camera occlusion') ([Drawing.RectangleF]::new(1302,806,702,156)) (C '#F09A78') $cardTitle $cardBody;Draw-Card $g 'NEXT MODEL GATE' @('Blender front/rear/gameplay-quarter proof','Humanoid joints + lance grip/stow sockets','rig, camera and animation: NOT TESTED') ([Drawing.RectangleF]::new(1302,976,702,192)) (C '#8FA8BD') $cardTitle $cardBody;$sr=[Drawing.RectangleF]::new(44,1194,1960,196);$sf=[Drawing.SolidBrush]::new((C '#08121F'));$sp=[Drawing.Pen]::new((C '#3B294D'),1.5);$amber=[Drawing.SolidBrush]::new((C '#F7B95A'));try{$g.FillRectangle($sf,$sr);$g.DrawRectangle($sp,$sr.X,$sr.Y,$sr.Width,$sr.Height);Draw-Text $g 'REVIEW ONLY / HUMAN APPROVAL NOT GRANTED' $status $amber ([Drawing.RectangleF]::new(70,1218,820,32));Draw-Text $g '2D ratio PASS 7.30H. 3D concept-space PASS 5.75H only.' $statusSmall $white ([Drawing.RectangleF]::new(70,1265,1000,28));Draw-Text $g 'Blender mesh, Humanoid rig, joint clearance, gameplay camera, animation and sockets remain NOT TESTED.' $statusSmall $muted ([Drawing.RectangleF]::new(70,1302,1400,28));Draw-Text $g 'Fictional energy observation lance / no real-firearm replica / external-IP review Pending' $statusSmall $amber ([Drawing.RectangleF]::new(70,1339,1300,28));Draw-Text $g 'Deterministic composite: tools/art/Build-Iris2DTo3DTranslationReview.ps1' $statusSmall $muted ([Drawing.RectangleF]::new(1210,1340,750,28))}finally{$amber.Dispose();$sp.Dispose();$sf.Dispose()}}finally{$line.Dispose();$muted.Dispose();$white.Dispose();$bg.Dispose()};$o.Save($out,[Drawing.Imaging.ImageFormat]::Png);[pscustomobject]@{Output=$out;Dimensions='2048x1440';TwoDHeads=7.30;ThreeDHeads=5.75;Status='REVIEW ONLY';HumanApproval='NOT GRANTED';ImplementationProof='NOT TESTED'}}finally{$statusSmall.Dispose();$status.Dispose();$cardBody.Dispose();$cardTitle.Dispose();$guideFont.Dispose();$chip.Dispose();$small.Dispose();$panelTitle.Dispose();$sub.Dispose();$title.Dispose();$g.Dispose();$o.Dispose();$ref.Dispose();$key.Dispose()}
